import requests
q='("ultradian" OR ultrarapid OR "rapid cycling") AND (COMT OR catechol-O-methyltransferase) AND (bipolar OR mania)'
r=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi',params={'db':'pubmed','term':q,'retmax':20,'retmode':'json'},timeout=20)
print('status',r.status_code)
j=r.json(); ids=j.get('esearchresult',{}).get('idlist',[]); print('ids',ids)
if ids:
 x=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20).json()
 for i in ids:
  d=x['result'][i]; print(i,d.get('pubdate'),d.get('title'),d.get('fulljournalname'))
else: print('No matching PubMed records')
